  "普通网页登录默认 12 小时；0 表示不自动过期。网页记住登录后，使用时自动续期，闲置 7 天后过期。手机 App 登录或扫码后持续信任。修改账号或登录方式会使登录失效；修改密码时可选择是否保留已绑定手机。": "普通网页登录默认 12 小时；0 表示不自动过期。网页记住登录后，使用时自动续期，闲置 7 天后过期。手机 App 登录或扫码后持续信任。修改账号或登录方式会使登录失效；修改密码时可选择是否保留已绑定手机。",
