  "1. 手动准备服务器（首次配置）": "1. 手动准备服务器（首次配置）",
  "安装服务、修改防火墙和 SSH 权限等管理员操作，请由你或服务器管理员在终端手动完成。App 不接收 sudo 密码，也不执行服务器安装命令。": "安装服务、修改防火墙和 SSH 权限等管理员操作，请由你或服务器管理员在终端手动完成。App 不接收 sudo 密码，也不执行服务器安装命令。",
  "将自己的域名解析到服务器公网 IP；配置 HTTPS 入口所需的 DNS、防火墙和安全组。": "将自己的域名解析到服务器公网 IP；配置 HTTPS 入口所需的 DNS、防火墙和安全组。",
  "准备普通 SSH 用户，允许远程端口转发；保持 GatewayPorts no，回环端口不要向公网开放。": "准备普通 SSH 用户，允许远程端口转发；保持 GatewayPorts no，回环端口不要向公网开放。",
