  "示例用户名 try2love 和域名 try2love.com 仅用于配置演示，请替换为自己的配置；示例地址不是在线演示站点。": "示例用户名 try2love 和域名 try2love.com 仅用于配置演示，请替换为自己的配置；示例地址不是在线演示站点。",
  "固定 HTTPS · 请检测入口": "固定 HTTPS · 请检测入口",
  "首次配置：从购买域名到手机访问": "首次配置：从购买域名到手机访问",
  "在 Cloudflare 添加根域名，例如 try2love.com，取得分配给你的两条名称服务器（NS）地址。": "在 Cloudflare 添加根域名，例如 try2love.com，取得分配给你的两条名称服务器（NS）地址。",
  "在阿里云等域名注册商修改“DNS 服务器”为这两条 NS，等待 Cloudflare 显示 Active。域名仍在原注册商续费；已有网站和邮箱需保留原解析记录。": "在阿里云等域名注册商修改“DNS 服务器”为这两条 NS，等待 Cloudflare 显示 Active。域名仍在原注册商续费；已有网站和邮箱需保留原解析记录。",
  "在 Cloudflare 的 Tunnels / 隧道中创建 Cloudflared 隧道，复制安装命令中的 Tunnel Token。这里只需要 Token，不需要整条命令或 API Key；App 已内置程序，无需重复安装服务。": "在 Cloudflare 的 Tunnels / 隧道中创建 Cloudflared 隧道，复制安装命令中的 Tunnel Token。这里只需要 Token，不需要整条命令或 API Key；App 已内置程序，无需重复安装服务。",
  "在本卡片填写 https://codex.try2love.com 和 Token，启用并保存，启动网关；回到 Cloudflare 确认连接器已连接。": "在本卡片填写 https://codex.try2love.com 和 Token，启用并保存，启动网关；回到 Cloudflare 确认连接器已连接。",
  "在隧道 Routes / 路由中添加 Published application / 公开主机名：子域名 codex，选择自己的域名，路径留空；服务类型 HTTP，服务地址使用下方电脑网关地址。保存时会创建对应 DNS 记录。": "在隧道 Routes / 路由中添加 Published application / 公开主机名：子域名 codex，选择自己的域名，路径留空；服务类型 HTTP，服务地址使用下方电脑网关地址。保存时会创建对应 DNS 记录。",
  "点击“检测固定入口”，再用手机关闭 Wi-Fi 后访问域名，验证登录和聊天。隧道显示 Healthy 不代表网页已经可用；电脑、Codex 和网关需要保持在线。": "点击“检测固定入口”，再用手机关闭 Wi-Fi 后访问域名，验证登录和聊天。隧道显示 Healthy 不代表网页已经可用；电脑、Codex 和网关需要保持在线。",
  "找不到域名：检查 NS、Active 状态和 DNS 缓存；1033：检查 Token 与隧道连接；502：检查电脑网关、HTTP 服务类型和端口。": "找不到域名：检查 NS、Active 状态和 DNS 缓存；1033：检查 Token 与隧道连接；502：检查电脑网关、HTTP 服务类型和端口。",
