  "Bark：填写手机 App 首页推送地址中的服务地址与 Device Key。ntfy：生成随机主题，并在手机订阅相同服务与主题。": "Bark：填写手机 App 首页推送地址中的服务地址与 Device Key。ntfy：生成随机主题，并在手机订阅相同服务与主题。",
  "开启需要的通道，点击底部“保存配置”，再分别发送测试通知。请在手机确认收到；服务接受不等于手机已收到。": "开启需要的通道，点击底部“保存配置”，再分别发送测试通知。请在手机确认收到；服务接受不等于手机已收到。",
  "先核对 Bark 服务地址与 Device Key，或 ntfy 服务地址、主题和 Token；自建 Bark 的设备需在该服务注册。": "先核对 Bark 服务地址与 Device Key，或 ntfy 服务地址、主题和 Token；自建 Bark 的设备需在该服务注册。",
  "服务已接受但手机没提示：检查系统通知权限、专注模式和手机网络。Android 还需允许 ntfy 在后台运行。": "服务已接受但手机没提示：检查系统通知权限、专注模式和手机网络。Android 还需允许 ntfy 在后台运行。",
  "登录设备": "登录设备",
  "登录有效期（小时）": "登录有效期（小时）",
  "默认 12 小时；0 表示不自动过期。网关重启保留登录。修改账号、密码、登录方式或有效期后，重启网关将要求重新登录。清除浏览器数据或更换访问域名也需要重新登录。": "默认 12 小时；0 表示不自动过期。网关重启保留登录。修改账号、密码、登录方式或有效期后，重启网关将要求重新登录。清除浏览器数据或更换访问域名也需要重新登录。",
  "刷新设备列表": "刷新设备列表",
  "每条记录代表一次浏览器登录。撤销登录会要求重新验证；封禁 IP 会同时阻止使用该 IP 的所有设备，包括重新登录。": "每条记录代表一次浏览器登录。撤销登录会要求重新验证；封禁 IP 会同时阻止使用该 IP 的所有设备，包括重新登录。",
  "网页无法读取网卡 MAC。手机可能使用私有 MAC，IP 也会随网络变化；共用公网 IP 的设备会一起受到 IP 规则影响。": "网页无法读取网卡 MAC。手机可能使用私有 MAC，IP 也会随网络变化；共用公网 IP 的设备会一起受到 IP 规则影响。",
