  "黑名单优先。规则保存后立即生效，被排除的登录会被撤销。规则不影响电脑端管理，可在这里解除限制。": "黑名单优先。规则保存后立即生效，被排除的登录会被撤销。规则不影响电脑端管理，可在这里解除限制。",
