  "仅在使用 NAS 等 HTTPS 反向代理时填写直连网关的代理 IP。代理必须覆盖或追加 X-Forwarded-For；本机 HTTPS 隧道自动受信任。未正确转发时显示代理 IP，封禁它会影响所有经该代理访问的设备。": "仅在使用 NAS 等 HTTPS 反向代理时填写直连网关的代理 IP。代理必须覆盖或追加 X-Forwarded-For；本机 HTTPS 隧道自动受信任。未正确转发时显示代理 IP，封禁它会影响所有经该代理访问的设备。",
