  "Confirm that all tasks in this configuration, including tasks in other clients, have finished and synchronize the shared Codex account? Do not start work in other clients until switching completes. The idle shared service exits normally only when needed.": "确认此配置中的所有任务（包括其他客户端的任务）均已结束，并同步共享的 Codex 账号？切换完成前请勿在其他客户端启动任务；仅在必要时正常退出空闲的共享服务。",
  "Confirm that all tasks, including tasks not shown on this web page, have finished and switch shared Codex access? Do not start work in other clients until switching completes. The desktop runtime quits normally and restarts only when needed.": "确认所有任务（包括此网页未显示的任务）均已结束，并切换共享 Codex 接入？切换完成前请勿启动其他客户端任务；仅在必要时正常退出并重启桌面运行时。",
