  "Standard web sign-in defaults to 12 hours; 0 disables expiry for web sign-ins. Remembered web sign-ins renew on use and expire after 7 inactive days. Mobile app sign-ins and pairing remain trusted until you sign out or revoke the device. Account or sign-in mode changes revoke all sign-ins; a password change can keep already bound phones.": "普通网页登录默认 12 小时；0 表示关闭网页登录过期。记住登录后，使用时自动续期，闲置 7 天后过期。手机 App 登录和扫码绑定保持信任，直到退出登录或撤销设备。修改账号或登录方式会使所有登录失效；修改密码时可保留已绑定手机。",
